"""Load the *trusted* model generated by our LinuxONE training script."""
from pathlib import Path


def load_model(path):
    import joblib  # The Mac's scanner-only tests need not install sklearn.

    model_path = Path(path).expanduser().resolve(strict=True)
    # Only load a joblib file you generated yourself; loading is code execution.
    return joblib.load(model_path)
